fn fibonacci(n: usize) -> Vec<i32> {
    if n == 0 {
        return Vec::new();
    }
    
    let mut result = vec![0; n];
    
    if n == 1 {
        return result;
    }
    
    result[1] = 1;
    
    for i in 2..n {
        result[i] = result[i - 1] + result[i - 2];
    }
    
    result
}